New-Item -ItemType Directory -Path $stageRoot -Force | Out-Null
$stageAsar = Join-Path $stageRoot 'app.asar'
$stageUnpacked = Join-Path $stageRoot 'app.asar.unpacked'
npx.cmd --yes @electron/asar pack $unpackedApp $stageAsar --unpack-dir node_modules
if ($LASTEXITCODE -ne 0) { throw 'asar pack failed' }
Assert-PathExists $stageAsar 'staged app.asar'
Assert-PathExists $stageUnpacked 'staged app.asar.unpacked'
$runtimeUnpacked = Join-Path $resources 'app.asar.unpacked'
$runtimeUnpackedBackup = Join-Path $resources 'app.asar.unpacked.original'
if (-not (Test-Path -LiteralPath $runtimeUnpackedBackup) -and (Test-Path -LiteralPath $runtimeUnpacked)) {
    Move-Item -LiteralPath $runtimeUnpacked -Destination $runtimeUnpackedBackup
}
Move-Item -LiteralPath $stageAsar -Destination $asar -Force
Move-Item -LiteralPath $stageUnpacked -Destination $runtimeUnpacked -Force
Write-Host "Repack complete"

Write-Host "PATCH_COPY=$destApp"
Write-Host "PATCH_TARGET=$($target.FullName)"
Write-Host "PATCH_BACKUP=$origBackup"

const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const target = process.argv[2];
if (!target) throw new Error('missing target path');

const oldPattern = 'if(u?n.has(r.model):!r.hidden)';
const newPattern = 'if(!r.hidden||u&&n.has(r.model))';
const source = fs.readFileSync(target, 'utf8');
const count = (text, pattern) => text.split(pattern).length - 1;

if (count(source, oldPattern) !== 1 || count(source, newPattern) !== 0) {
  throw new Error(`unexpected patch signature before replace: old=${count(source, oldPattern)} new=${count(source, newPattern)}`);
}

const backup = `${target}.orig`;
if (!fs.existsSync(backup)) {
  fs.copyFileSync(target, backup);
}

const patched = source.replace(oldPattern, newPattern);
if (count(patched, oldPattern) !== 0 || count(patched, newPattern) !== 1) {
  throw new Error(`unexpected patch signature after replace: old=${count(patched, oldPattern)} new=${count(patched, newPattern)}`);
}

fs.writeFileSync(target, patched);
execFileSync('node', ['--check', target], { stdio: 'inherit' });
const crypto = require('crypto');
const hash = crypto.createHash('sha256').update(fs.readFileSync(target)).digest('hex');
console.log('patched:', path.basename(target));
console.log('sha256:', hash);

const http = require('http');
const WebSocket = require('ws');

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function fetchJson(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let data = '';
      res.on('data', (chunk) => (data += chunk));
      res.on('end', () => {
        try {
          resolve(JSON.parse(data));
        } catch (err) {
          reject(err);
        }
      });
    }).on('error', reject);
  });
}

async function cdp(wsUrl, method, params = {}, sessionId) {
  const ws = new WebSocket(wsUrl);
  const id = 1;
  return new Promise((resolve, reject) => {
    ws.on('open', () => {
      ws.send(JSON.stringify({ id, method, params, sessionId }));
    });
    ws.on('message', (raw) => {
      const msg = JSON.parse(raw.toString());
      if (msg.id === id) {
        ws.close();
        if (msg.error) reject(new Error(JSON.stringify(msg.error)));
        else resolve(msg.result);
      }
    });
    ws.on('error', reject);
  });
}

async function evalInPage(wsUrl, expression) {
  const ws = new WebSocket(wsUrl);
  let msgId = 0;
  const send = (payload) => new Promise((resolve, reject) => {
    const current = ++msgId;
    const handler = (raw) => {
      const msg = JSON.parse(raw.toString());
      if (msg.id === current) {
        ws.off('message', handler);
        if (msg.error) reject(new Error(JSON.stringify(msg.error)));
        else resolve(msg.result);
      }
    };
    ws.on('message', handler);
    ws.send(JSON.stringify({ id: current, ...payload }));
  });

  await new Promise((resolve, reject) => {
    ws.on('open', resolve);
    ws.on('error', reject);
  });

  const { frameTree } = await send({ method: 'Page.getFrameTree' });
  const world = await send({
    method: 'Page.createIsolatedWorld',
    params: { frameId: frameTree.frame.id, worldName: 'codex-gpt56-check' },
  });

  const result = await send({
    method: 'Runtime.evaluate',
    params: {
      contextId: world.executionContextId,
      expression,
      returnByValue: true,
      awaitPromise: true,
    },
  });

  ws.close();
  return result.result.value;
}

async function main() {
  const deadline = Date.now() + 90000;
  let targets = [];
  while (Date.now() < deadline) {
    try {
      targets = await fetchJson('http://127.0.0.1:9222/json/list');
      const codex = targets.find((t) => t.title === 'Codex' && String(t.url || '').startsWith('app://-/'));
      if (codex) {
        console.log('page_ok', codex.title, codex.url);
        const triggerText = await evalInPage(
          codex.webSocketDebuggerUrl,
          `(() => {
            const el = document.querySelector('[data-codex-intelligence-trigger]');
            return el ? (el.textContent || '').trim() : null;
          })()`
        );
        console.log('trigger_text', triggerText || '(missing)');

        const menuProbe = await evalInPage(
          codex.webSocketDebuggerUrl,
          `(() => {
            const trigger = document.querySelector('[data-codex-intelligence-trigger]');
            if (!trigger) return { error: 'no trigger' };
            trigger.click();
            const items = [...document.querySelectorAll('[role="menuitem"]')].map((n) => (n.textContent || '').trim()).filter(Boolean);
            return { items };
          })()`
        );
        console.log('menu_items', JSON.stringify(menuProbe));
        return;
      }
    } catch (_) {}
    await sleep(3000);
  }
  console.log('page_timeout', JSON.stringify(targets.map((t) => ({ title: t.title, url: t.url }))));
  process.exitCode = 1;
}

main().catch((err) => {
  console.error('dom_check_failed', err.message);
  process.exitCode = 1;
});
